for r in eligible:
    if r['case'] not in seen:
        chosen.append({'case': r['case'], 'component': r['component'], 'expected_annotation_gap_mm': r['quantities']['canal']['gap_mm'], 'source_label_sha256': r['source_case_label_sha256']})
